function makeEnvironment(){const e=new T.Scene();e.background=new T.Color('#bfc7b6');for(const p of [[-3,4,2,6,5],[4,2,-1,3,6],[0,5,-4,6,3]]){const o=new T.Mesh(new T.PlaneGeometry(p[3],p[4]),new T.MeshBasicMaterial({color:'#fff8e2'}));o.position.set(p[0],p[1],p[2]);o.lookAt(0,0,0);e.add(o);}const pm=new T.PMREMGenerator(viewRenderer);const tex=pm.fromScene(e,.04).texture;pm.dispose();return tex;}
function initViewer(){if(viewRenderer)return;viewRenderer=makeRenderer(true);viewRenderer.setPixelRatio(Math.min(devicePixelRatio,2));viewRenderer.toneMapping=T.ACESFilmicToneMapping;viewRenderer.toneMappingExposure=1.4;$('#viewer').append(viewRenderer.domElement);viewScene=new T.Scene();if(!viewSoftware)viewScene.environment=makeEnvironment();else viewScene.add(new T.AmbientLight('#aaa88e',.5));viewCamera=new T.PerspectiveCamera(36,1,.1,30);viewCamera.position.set(0,.5,4.5);viewCamera.lookAt(0,0,0);viewScene.add(new T.HemisphereLight('#fff6d9','#53684e',2.5));const l=new T.DirectionalLight('#fff2cf',4);l.position.set(-3,4,3);viewScene.add(l);const l2=new T.DirectionalLight('#b1d4de',3);l2.position.set(3,2,-2);viewScene.add(l2);const cv=viewRenderer.domElement;cv.addEventListener('pointerdown',e=>{dragging=true;dragPos=[e.clientX,e.clientY];cv.setPointerCapture(e.pointerId);});cv.addEventListener('pointermove',e=>{if(!dragging||!viewObject)return;viewObject.rotation.y+=(e.clientX-dragPos[0])*.012;viewObject.rotation.x=Math.max(-1.1,Math.min(1.1,viewObject.rotation.x+(e.clientY-dragPos[1])*.009));dragPos=[e.clientX,e.clientY];});cv.addEventListener('pointerup',()=>dragging=false);cv.addEventListener('pointercancel',()=>dragging=false);cv.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.min(7,Math.max(2.7,zoom+e.deltaY*.004));viewCamera.position.z=zoom;viewCamera.lookAt(0,0,0);},{passive:false});}
function resizeView(){if(!viewRenderer||!current||!$('#detail').open)return;const b=$('#viewer').getBoundingClientRect();viewRenderer.setSize(b.width,b.height);viewCamera.aspect=b.width/b.height;viewCamera.updateProjectionMatrix();if(viewObject)viewRenderer.render(viewScene,viewCamera);}
let lastFocus;
function openDetail(id,changeHash=true){if(!data[id])return;lastFocus=document.activeElement;current=id;$('#tooltip').style.display='none';const d=data[id];$('#model-index').textContent=`ОБЪЕКТ ${d.index} / 05`;$('#model-type').textContent=d.model?'ИССЛЕДОВАТЬ ФОРМУ':'ИЗ БЛОКНОТА МАСТЕРСКОЙ';$('#detail-kicker').textContent=d.kicker;$('#detail-title').innerHTML=d.title;$('#detail-description').textContent=d.description;$('#detail-specs').innerHTML=d.specs.map(([a,b])=>`<div class="spec-row"><span>${a}</span><span>${b}</span></div>`).join('');$('#detail-extra').textContent=d.extra;$('#detail-link').textContent=id==='about'?'Связаться в Instagram →':id==='engineering'?'Обсудить инженерный проект →':'Написать об этом предмете →';$('#detail-link').href='https://www.instagram.com/yazhemoh/';$('#model-disclaimer').hidden=id!=='portfolio';$('#viewer-hint').hidden=!d.model;$('#viewer-hint').textContent='↔ Потяните, чтобы вращать · колёсико для масштаба';$('#reset').hidden=!d.model;
if(!$('#detail').open)$('#detail').showModal();$('.detail-copy').scrollTop=0;$('#detail').scrollTop=0;
if(d.model){$('#viewer').style.display='block';$('#visual-card').style.display='none';try{initViewer();if(viewObject){viewScene.remove(viewObject);}viewObject=new T.Group();const m=d.model(true);viewObject.add(m);viewObject.rotation.set(.12,-.35,0);viewScene.add(viewObject);zoom=id==='portfolio'?5:4.5;viewCamera.position.set(0,.4,zoom);viewCamera.lookAt(0,0,0);resizeView();viewRenderer.render(viewScene,viewCamera);
loadProduct(d.modelKind,'detail').then(()=>{if(current!==id||!$('#detail').open)return;const m=d.model(true);viewObject.clear();viewObject.add(m);viewRenderer.render(viewScene,viewCamera);}).catch(e=>{console.error(e);if(current!==id)return;$('#viewer-hint').textContent='Доступна облегчённая модель · потяните, чтобы вращать';});
}catch(e){$('#viewer-hint').textContent='3D-просмотр недоступен на этом устройстве';console.error(e);}}
else{$('#viewer').style.display='none';$('#visual-card').style.display='block';$('#visual-card').innerHTML=d.visual;}
if(changeHash)history.pushState(null,'',`#${id}`);}
function closeDetail(){if($('#detail').open)$('#detail').close();current=null;dragging=false;history.replaceState(null,'',location.pathname+location.search);lastFocus?.focus();}
$('#close').onclick=closeDetail;$('#detail').addEventListener('cancel',e=>{e.preventDefault();closeDetail();});$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail();}});
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));$('.brand').onclick=e=>{e.preventDefault();closeDetail();};$('#reset').onclick=()=>{if(viewObject){viewObject.rotation.set(.12,-.35,0);zoom=current==='portfolio'?5:4.5;viewCamera.position.set(0,.4,zoom);viewCamera.lookAt(0,0,0);}};
$('#lighting').onclick=()=>{night=!night;document.body.classList.toggle('night',night);$('#lighting').innerHTML=night?'◑ <span>Вечерний свет</span>':'◐ <span>Дневной свет</span>';$('#lighting').setAttribute('aria-label',night?'Включить дневной свет':'Включить вечерний свет');if(scene){scene.background.set(night?'#26362f':'#d8d7cb');scene.fog.color.copy(scene.background);ambient.intensity=night?.5:2.3;sun.intensity=night?.25:3.4;lampLight.intensity=night?5:.65;screenLight.intensity=night?2:.4;renderer.toneMappingExposure=night?1.25:1.15;if(software){ambient.color.set(night?'#4d6254':'#979d88');sun.color.set(night?'#263d36':'#9d987d');lampLight.color.set(night?'#abc78c':'#31493a');}dirty=true;renderer.invalidate?.();if(software){renderer.render(scene,camera);dirty=false;}}};
$('#help').onclick=()=>{$('#help-panel').hidden=!$('#help-panel').hidden;$('#help').setAttribute('aria-expanded',String(!$('#help-panel').hidden));};$('#help-close').onclick=()=>{$('#help-panel').hidden=true;$('#help').setAttribute('aria-expanded','false');$('#help').focus();};addEventListener('resize',resize);addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(data[id])openDetail(id,false);else if(current)closeDetail();});
try{await loadRoomModels();createRoom();}catch(e){console.error(e);$('#loading')?.remove();$('#scene-error').hidden=false;}
